DO $$BEGIN IF to_regclass('domainspec_dead_letter') IS NULL THEN RAISE EXCEPTION 'missing table: domainspec_dead_letter'; END IF; IF EXISTS (SELECT * FROM (VALUES ('id','text','NO'),('source_channel_ref','text','NO'),('message_type_ref','text','NO'),('payload','jsonb','NO'),('failure_class','text','NO'),('failed_at','timestamp with time zone','NO'),('redriven_at','timestamp with time zone','YES')) AS expected(column_name,data_type,is_nullable) EXCEPT SELECT column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema=current_schema() AND table_name='domainspec_dead_letter') THEN RAISE EXCEPTION 'column contract mismatch: domainspec_dead_letter'; END IF; END$$;
